package com.rikkeibank.notification.config; import java.nio.charset.StandardCharsets; import java.util.*; import javax.crypto.SecretKey; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.core.convert.converter.Converter; import org.springframework.security.authentication.AbstractAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.config.web.server.ServerHttpSecurity; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.security.web.server.SecurityWebFilterChain; import reactor.core.publisher.Mono;
@Configuration public class SecurityConfig{@Bean ReactiveJwtDecoder jwtDecoder(@Value("${app.jwt.secret}")String secret){SecretKey key=new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256");return NimbusReactiveJwtDecoder.withSecretKey(key).build();}@Bean Converter<Jwt,Mono<AbstractAuthenticationToken>> converter(){return jwt->{List<String> roles=jwt.getClaimAsStringList("roles");var auth=roles==null?List.<SimpleGrantedAuthority>of():roles.stream().map(r->new SimpleGrantedAuthority("ROLE_"+r)).toList();return Mono.just(new JwtAuthenticationToken(jwt,auth));};}@Bean SecurityWebFilterChain chain(ServerHttpSecurity http,Converter<Jwt,Mono<AbstractAuthenticationToken>> c){return http.csrf(ServerHttpSecurity.CsrfSpec::disable).authorizeExchange(a->a.pathMatchers("/actuator/health").permitAll().pathMatchers("/api/notifications/**").hasAnyRole("ADMIN","TELLER").anyExchange().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(c))).build();}}
